<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';rh24_require_login();if(!rh24_can('pos_reports')&&!rh24_can('pos_close_shift')){http_response_code(403);exit('Kein Zugriff.');}$id=trim((string)($_GET['id']??''));$q=rh24_db()->prepare("SELECT z.*,r.name register_name,r.code register_code,u.display_name user_name FROM pos_daily_closings z JOIN pos_registers r ON r.id=z.register_id LEFT JOIN users u ON u.id=z.user_id WHERE z.id=?");$q->execute([$id]);$z=$q->fetch();if(!$z){http_response_code(404);exit('Abschluss nicht gefunden.');}$p=rh24_json_decode($z['payments_json']??'',[]);$m=fn($v)=>number_format((float)$v,2,',','.').' €';?><!doctype html><html lang="de"><head><meta charset="utf-8"><title>Z-Abschluss <?=htmlspecialchars($z['z_report_no'])?></title><style>body{font:14px Arial;color:#17120f;background:#eee}.sheet{max-width:760px;margin:24px auto;background:#fff;padding:38px;border-radius:16px}.row{display:flex;justify-content:space-between;border-bottom:1px solid #eee;padding:9px 0}.big{font-size:22px;font-weight:800}.warn{font-weight:800;color:#a33}button{padding:10px 16px}@media print{body{background:#fff}.sheet{margin:0;box-shadow:none}.no{display:none}}</style></head><body><div class="no" style="max-width:760px;margin:15px auto"><button onclick="print()">Drucken / PDF</button></div><main class="sheet"><h1>Z-Abschluss</h1><p><b><?=htmlspecialchars($z['z_report_no'])?></b> · <?=htmlspecialchars($z['register_code'].' · '.$z['register_name'])?><br><?=htmlspecialchars($z['business_date'])?> · <?=htmlspecialchars((string)$z['user_name'])?></p><div class="row big"><span>Netto-Kassenumsatz</span><span><?=$m($z['net_sales'])?></span></div><div class="row"><span>Bruttoverkäufe</span><span><?=$m($z['gross_sales'])?></span></div><div class="row"><span>Erstattungen</span><span><?=$m($z['refunds'])?></span></div><div class="row"><span>Umsatzsteuer</span><span><?=$m($z['tax_total'])?></span></div><h3>Zahlarten</h3><?php foreach($p as $x):?><div class="row"><span><?=htmlspecialchars((string)$x['payment_method'])?></span><span><?=$m($x['amount'])?></span></div><?php endforeach;?><h3>Kassensturz</h3><div class="row"><span>Soll-Bargeld</span><span><?=$m($z['cash_expected'])?></span></div><div class="row"><span>Gezählt</span><span><?=$m($z['cash_counted'])?></span></div><div class="row <?=abs((float)$z['cash_difference'])>.009?'warn':''?>"><span>Differenz</span><span><?=$m($z['cash_difference'])?></span></div><p><small>Abgeschlossen: <?=htmlspecialchars($z['closed_at'])?> · Orgaboard POS V94</small></p></main></body></html>
